mapper.select:
SELECT id, file_no, task_no, settle_date, member_id, file_type, file_name, file_size, file_md5, storage_bucket, storage_path, version, status, publish_time, download_count, created_at, updated_at FROM settle_file
AND settle_date = #{settleDate}
AND member_id = #{memberId}
AND file_type = #{fileType}
ORDER BY settle_date DESC, member_id ASC, file_type ASC, version ASC

mapper.update:
UPDATE settle_file
SET download_count = download_count + 1
WHERE file_no = #{fileNo}
